#!/usr/bin/env python3
"""Summarize a completed fresh-hand run; never turns progress into a PASS."""
import bisect,gzip,json,math,sys
from pathlib import Path
p=Path(sys.argv[1]);r=json.loads((p/'0-report.json').read_text());v=json.loads((p/'resource-verification.json').read_text())
assert r['status']=='PASS' and v['status']=='PASS' and r['completedHands']==r['goalHands']
q=lambda values: {k:(sorted(values)[max(0,math.ceil(len(values)*n)-1)] if values else None) for k,n in [('p50',.5),('p95',.95),('p99',.99),('max',1)]}|{'samples':len(values)}
checkpoints=r['resourceCheckpoints'];milestones=[x for x in checkpoints if x['completedHands']>0 and x['label']!='final.cashout'];cutoffs=[x['decisions'] for x in milestones];groups={};ordinary=[]
with gzip.open(p/'0-trace.jsonl.gz','rt') as f:
 for line in f:
  row=json.loads(line)
  if row['name']=='ordinary.bot.prepare':
   ordinary.append(row['ms']);index=bisect.bisect_left(cutoffs,row['decision']);end=milestones[index]['completedHands'] if index<len(milestones) else r['goalHands'];groups.setdefault(end,[]).append(row['ms'])
assert len(ordinary)==r['decisions']==r['ordinaryPreparation']['samples']
peak_memory={key:max(x['memory'][key] for x in r['memory']) for key in ['heapUsed','heapTotal','rss','external','arrayBuffers']}
rows=[{'completedHands':x['completedHands'],'label':x['label'],'elapsedSeconds':x['elapsedMs']/1000,'logicalStorageBytes':x['storage']['totalBytes'],'canonicalHandsBytes':x['storage']['groups'].get('canonicalHands',{}).get('bytes',0),'checkpointBytes':x['storage']['groups'].get('checkpointGenerations',{}).get('bytes',0),'journalBytes':x['storage']['groups'].get('incrementalJournal',{}).get('bytes',0),'postGCHeapBytes':x['postGCMemory']['heapUsed'],'naturalHeapBytes':x['naturalMemory']['heapUsed'],'rssBytes':x['postGCMemory']['rss'],'liveTimers':x['liveTimers']} for x in checkpoints]
summary={'status':'PASS','applicationCommit':r['source']['applicationCommit'],'reconstructionCommit':r['source']['repositoryHead'],'environment':r['environment'],'initialHands':r['initialHands'],'completedHands':r['completedHands'],'botPreparations':r['decisions'],'actions':r['actions'],'sessions':r['sessions'],'handsBySeats':r['handsBySeats'],'endings':r['endings'],'preparationMs':q(ordinary),'preparationWindowsByCompletedHandCheckpoint':{str(k):q(a) for k,a in groups.items()},'preparationBySeat':r['preparationBySeat'],'preparationsOver1000ms':sum(x>1000 for x in ordinary),'preparationsOver10000ms':sum(x>10000 for x in ordinary),'maximumTimers':r['maximumTimers'],'timersAfterClose':r['timersAfterClose'],'pendingReloadAndStaleCommitChecks':len(r['reloads']),'playElapsedSeconds':r['playElapsedMs']/1000,'nodeEventLoopDelayMs':r['nodeEventLoopDelay'],'initialEmptyRecoveryMs':r['fastRecovery'],'recoveryAndAuditOperationMs':{k:v for k,v in r['windows']['byOperation'].items() if 'Recovery' in k or k.startswith('history.') or k.startswith('audit.')},'memorySamplesByPhase':r['memory'],'resources':rows,'coarsePeakMemoryBytes':peak_memory,'finalStorage':r['finalStorage'],'finalAccounting':r['finalCompactAccount'],'independentFullReplayAgreement':True,'archiveAudit':'PASS','historical10072msOutlier':'UNATTRIBUTED; neither absence nor a new measured slow operation identifies that historical event','limits':['Fresh play includes zero preconstructed hands.','Node24 disk-backed request reference, not actual native browser or device performance.','Memory includes growing diagnostic window/context arrays, reference-store indexes and canonical app records; not pure application memory.','Canonical historical records intentionally grow; only redundant caches/journals/checkpoints have fixed bounds.','Physical origin storage usage and INP are not measured by this harness.','Controller reloads retain module caches and store index in this process; not browser/process-cold startup.','Node event-loop delay includes checkpoint forced GC, independent accounting and synchronous diagnostic writes.','Fullrun includes disclosed concurrent regression intervals; see concurrent-work.json, and do not treat shared-host latency as an isolated matched comparison.']}
(p/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
lines=[f"# Step 5L fresh {r['completedHands']:,}-hand resource evidence",'',f"Completed **{r['completedHands']:,} new hands**, {r['decisions']:,} ordinary bot preparations, {r['actions']:,} actions and {r['sessions']} sessions from a zero-hand synthetic guest account. Exact full financial/chip replay and incremental/full statistics agree. This is a Node disk-reference harness, not a physical device or native browser measurement.",'',f"Application input identity: `{r['source']['applicationCommit']}`. Reconstructed repository checkpoint used to launch: `{r['source']['repositoryHead']}`.",'',f"Preparation latency milliseconds: p50 {q(ordinary)['p50']:.2f}; p95 {q(ordinary)['p95']:.2f}; p99 {q(ordinary)['p99']:.2f}; max {max(ordinary):.2f}. Samples above 1 second: {sum(x>1000 for x in ordinary)}. The historical 10.072-second observation remains unattributed.",'','| Completed hands | Logical storage MB | Post-GC heap MB | RSS MB | Elapsed seconds |','|---:|---:|---:|---:|---:|']
for row in rows:lines.append(f"|{row['completedHands']}|{row['logicalStorageBytes']/1e6:.2f}|{row['postGCHeapBytes']/1e6:.2f}|{row['rssBytes']/1e6:.2f}|{row['elapsedSeconds']:.2f}|")
lines+=['',f"Session splits: {r['handsBySeats']}. Pending reload/stale-commit checks: {len(r['reloads'])}. Controller intervals never exceeded {r['maximumTimers']} and dropped to {r['timersAfterClose']} after close.",'','Financial balances are integer cents: `'+json.dumps(r['finalCompactAccount'])+'`. Initial manual funding is excluded from poker profit.','', 'Recovery timings by completed-history milestone, pending recovery and full archive/audit are separated in summary.json; initial empty-account reloads are not large-history recovery measurements.', '', 'Full canonical hands remain preserved. Temporary packed replicas ≤120, checkpoint generations ≤2, journal records ≤126, policy caches ≤4/8. Historical storage growth is intentional and measured; these bounds do not make unlimited guest history fit every device.','', 'Raw receipts, source hashes, compressed trace, every canonical record, independent streamed BigInt replay and nine resource checks are retained beside this report. These check counts are not additional V7 acceptance IDs.']
(p/'REPORT.md').write_text('\n'.join(lines)+'\n');print(json.dumps({k:summary[k] for k in ['status','completedHands','botPreparations','preparationMs','playElapsedSeconds','pendingReloadAndStaleCommitChecks']}))
